int frame_free(blosc2_frame_s* frame) {
  if (frame->cframe != NULL && !frame->avoid_cframe_free) {
    free(frame->cframe);
  }
  if (frame->coffsets != NULL) {
    free(frame->coffsets);
  }
  if (frame->urlpath != NULL) {
    free(frame->urlpath);
  }
  free(frame);
  return 0;
}
```

